def transform(grid):
    h = len(grid)
    w = 7
    out = [[0] * w for _ in range(h)]

    # The marker gives the starting point of the path.
    mr = mc = 0
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value == 5:
                mr, mc = r, c - 8
                break
        else:
            continue
        break
    mc = max(0, min(w - 1, mc))
    out[mr][mc] = 5

    shapes = {
        ((1, 1, 0), (1, 0, 1), (0, 1, 0)): ("right", 3),  # A
        ((1, 0, 1), (1, 0, 1), (1, 1, 1)): ("left", 2),   # B
        ((1, 0, 1), (0, 1, 0), (0, 1, 0)): ("down", 2),   # C
        ((1, 1, 1), (0, 1, 0), (1, 0, 1)): ("left", 4),   # D
    }

    pieces = []
    # Read down the left stack, then down the right stack.
    for c0 in (0, 4):
        for r0 in range(0, h - 2, 4):
            block = [[grid[r0 + dr][c0 + dc] for dc in range(3)]
                     for dr in range(3)]
            color = next((v for row in block for v in row if v != 0), 0)
            if not color:
                continue
            mask = tuple(tuple(int(v != 0) for v in row) for row in block)
            if mask in shapes:
                direction, length = shapes[mask]
                pieces.append((color, direction, length))

    x = mc
    r = mr + 1
    for color, direction, length in pieces:
        if direction == "down":
            for rr in range(r, min(h, r + length)):
                if 0 <= x < w:
                    out[rr][x] = color
            r += length
        else:
            step = 1 if direction == "right" else -1
            for i in range(length):
                xx = x + step * i
                if 0 <= r < h and 0 <= xx < w:
                    out[r][xx] = color
            x += step * (length - 1)
            r += 1

    return out
